answer:
function mapValues<T extends object, R>(obj: T, f: (v: T[keyof T]) => R): { [K in keyof T]: R } {
  const out = {} as { [K in keyof T]: R };
  for (const k in obj) { out[k as keyof T] = f(obj[k as keyof T]); }
  return out;
}
